    /// <summary>
    /// Sums the log-probability of every consecutive letter pair in the text. Higher (less
    /// negative) means more English-like; this is the value <see cref="SimpleSubstitutionSolver"/>
    /// hill-climbs to maximise.
    /// </summary>
    public static double Score(string text)
    {
        string letters = FrequencyAnalysis.LettersOnly(text);
        double score = 0;

        for (int i = 0; i + 1 < letters.Length; i++)
        {
            int a = letters[i] - 'A';
            int b = letters[i + 1] - 'A';
            score += LogProbabilities[a, b];
        }

        return score;
    }
